// A PostgREST miss arrives as ZERO items, which stops a branch dead with no
// error at all. alwaysOutputData turns that into one empty item so we reach
// here and can say what actually went wrong.
function firstRow(nodeName){
  let items = [];
  try { items = $(nodeName).all().map(i => i.json).filter(Boolean); } catch (e) { return null; }
  for (const it of items){
    if (Array.isArray(it)){ if (it[0]) return it[0]; continue; }
    if (it && it.id) return it;
  }
  return null;
}

const profile = firstRow('Find Test Profile');
if (!profile) {
  throw new Error('no profile for mypaintr@gmail.com - check the Supabase key shape before anything else: sb_secret_ goes in the apikey header ONLY');
}

// Compute Access lets a render through on an active subscription OR on at
// least one credit. If neither holds, the pipeline answers 402 and we learn
// nothing about BFL - so top the test account up rather than burn the run.
const active = profile.subscription_status === 'active';
const credits = profile.credits_balance || 0;

return [{ json: {
  user_id: profile.id,
  email: profile.email,
  credits,
  subscription_active: active,
  needs_credit: !active && credits < 1,
  brand_logo_url: profile.brand_logo_url || null,
  brand_contact: profile.brand_contact || null
}, pairedItem: 0 }];

// Prefers a photo a real user has already uploaded, because that is the exact
// kind of URL the image service will be handed as original_url in production.
// Falls back to a fixture in the repo so the test still runs against an empty
// database - which is what it found on its first run.
function firstRow(nodeName){
  let items = [];
  try { items = $(nodeName).all().map(i => i.json).filter(Boolean); } catch (e) { return null; }
  for (const it of items){
    if (Array.isArray(it)){ if (it[0]) return it[0]; continue; }
    if (it && it.original_photo_url) return it;
  }
  return null;
}

const FIXTURE = 'https://raw.githubusercontent.com/practicalcrm/paintrzaip2p/main/workflows/selftest-kitchen.jpg';
const prior = firstRow('Find A Photo');
const photoUrl = (prior && prior.original_photo_url) || FIXTURE;

const profile = $('Read Profile').first().json;

// A dark navy on cabinets is the hardest case for the LAB pass: a big
// lightness move, so if mean-L retargeting is going to misbehave it shows here
// rather than on some safe greige.
return [{ json: {
  user_id: profile.user_id,
  original_photo_url: photoUrl,
  color_hex: '#232E38',
  color_name: 'Sherwin-Williams Naval (SW 6244)',
  surface: 'kitchen cabinets',
  prompt: 'Repaint the kitchen cabinets Sherwin-Williams Naval.',
  brand_logo_url: profile.brand_logo_url,
  brand_contact: profile.brand_contact
}, pairedItem: 0 }];

// Exactly the payload app.html posts, so this exercises the real contract
// rather than a convenient subset of it.
const inserted = $input.first().json;
const row = Array.isArray(inserted) ? inserted[0] : inserted;
if (!row || !row.id) throw new Error('insert returned no row: ' + JSON.stringify(inserted).slice(0, 400));

const test = $('Build Test Render').first().json;

return [{ json: {
  render_id: row.id,
  user_id: test.user_id,
  photo_url: test.original_photo_url,
  color_hex: test.color_hex,
  color_name: test.color_name,
  colors: [{ hex: test.color_hex, name: 'Naval', code: 'SW 6244', brand: 'Sherwin-Williams' }],
  surface: test.surface,
  prompt: test.prompt,
  brand_logo_url: test.brand_logo_url,
  brand_contact: test.brand_contact
}, pairedItem: 0 }];

// The webhook answers 200 on the happy path and 4xx/5xx when the pipeline
// refuses, but the row is the real record - a render that half-finished shows
// up here as done-with-no-urls, which a status code alone would hide.
function firstRow(nodeName){
  let items = [];
  try { items = $(nodeName).all().map(i => i.json).filter(Boolean); } catch (e) { return null; }
  for (const it of items){
    if (Array.isArray(it)){ if (it[0]) return it[0]; continue; }
    if (it && it.id) return it;
  }
  return null;
}

const row = firstRow('Read Result Row') || {};
const webhook = $('Fire Render Webhook').first().json;

const ok = row.status === 'done' && !!row.rendered_photo_url && !!row.branded_photo_url;

return [{ json: {
  passed: ok,
  render_id: row.id || null,
  row_status: row.status || 'row not found',
  rendered_photo_url: row.rendered_photo_url || null,
  branded_photo_url: row.branded_photo_url || null,
  webhook_response: webhook,
  next: ok
    ? 'open both URLs and judge the colour'
    : 'open the Render Pipeline execution list - the failing node names the cause'
}, pairedItem: 0 }];
